import {ohms,formatSWR} from './matching.js';
import {METERS_PER_FOOT} from './units.js';
import {C,TYPES,hexDimensions} from './model.js';
import {hasSoil,soilProperties,groundName} from './soil.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function buildReport({state:s,model:m,image,elevationSvg,azimuthSvg,created=new Date().toLocaleString('en-CA')}){
 const f=s.units==='ft'?1/METERS_PER_FOOT:1,n=(value,precision=2)=>Number(value).toFixed(precision),measure=value=>`${n(value*f)} ${s.units}`,soil=soilProperties(s);
 const rows=[['Antenna',TYPES[s.type].name],['Frequency',`${n(s.freq,3)} MHz`],['Wavelength',measure(C/s.freq)],['Wire '+(['loop','delta'].includes(s.type)?'perimeter':(s.type.startsWith('yagi')||s.type==='hexbeam')?'driven length':'length'),measure(s.length)],['Height reference',(['v','efv','delta'].includes(s.type)?'Apex':['monopole','invl'].includes(s.type)?'Feed base':['efsloper'].includes(s.type)?'Lower feed end':s.type==='uprightv'?'V feed':'Center')],['Height',`${measure(s.height)} / ${n(s.height/(C/s.freq))} λ`],[(s.type.startsWith('yagi')||s.type==='hexbeam')?'Beam bearing':'Wire bearing',`${n(s.bearing,1)}° from north`],['Ground / soil',groundName(s)]];
 if(hasSoil(s))rows.push(['Relative permittivity',`${n(soil.er)} εr`],['Conductivity',`${Number((soil.sigma*1000).toPrecision(6))} mS/m`]);
 if(s.type==='hexbeam'){const hex=hexDimensions(s);rows.push(['Reference','KIO / G3TXQ-inspired'],['Reflector length',measure(hex.reflector)],['Tip gap',measure(hex.gap)],['Turning radius',measure(hex.radius)]);}if(s.type==='monopole'){rows.push(['Return path',m.engine==='nec2'?'Explicit NEC return wires':s.returnMode==='ideal'?'Implicit ground':s.returnMode==='radials'?'Radial wires':'Counterpoise wire']);if(s.returnMode!=='ideal')rows.push(['Return wires',String(s.returnMode==='counterpoise'?1:s.radialCount)],['Each return length',measure(s.radialLength)],['Downward angle',`${n(s.radialSlope,1)}°`]);}if(s.type==='invl')rows.push(['Vertical rise',measure(s.rise)],['Horizontal run',measure(s.horizontal)],['Top height',measure(s.height+s.rise)]);
 if(['v','efv','uprightv'].includes(s.type))rows.push(['Included V angle',`${n(s.vangle,1)}°`]);
 if(['sloper','efsloper'].includes(s.type))rows.push(['Tilt from horizontal',`${n(s.tilt,1)}°`]);
 if(m.engine==='nec2')rows.push(['Solver / wire',`NEC2++ / ${s.wireDiameter} mm ${s.material}`],['Feed impedance',ohms(m.matching.raw[0])],['Device / SWR',`${s.matchRatio}:1 / ${formatSWR(Math.max(...m.matching.swrs))}`],['Radio / assumed loss',`${s.referenceZ} Ω / ${s.deviceLoss} dB`]);rows.push(['Angular sampling','5° azimuth / elevation'],['Pattern floor',`−${s.range} dB from peak`]);
 return `<article class="sheet-page${m.engine==='nec2'?' nec-sheet':''}"><div class="sheet-head"><div><b>FieldLab</b><span>ANTENNA PATTERN REPORT</span></div><p>${esc(created)}<br>${n(s.freq,3)} MHz · ${esc(groundName(s))}</p></div><div class="sheet-max"><div><span>MAXIMUM MODELED PATTERN</span><strong>${n(m.gain)} <small>dBi</small></strong><em>${m.engine==='nec2'?(s.gainMetric==='realized'?'Realized gain after device':'NEC gain · accepted antenna power'):'Preview directivity · not realized gain'}</em></div><div><span>AZIMUTH OF MAXIMUM</span><strong>${n(m.peakAz,1)}°</strong><em>Clockwise from north · 0° N / 90° E</em></div><div><span>ELEVATION OF MAXIMUM</span><strong>${n(m.peakEl,1)}°</strong><em>Above the horizon · 90° is straight up</em></div></div><div class="sheet-body"><section class="sheet-scene"><h3>3D pattern & antenna</h3>${image?`<img src="${esc(image)}" alt="3D antenna radiation pattern with the sampled maximum direction marked in cyan">`:'<p>3D rendering unavailable. Numerical results and cuts remain valid.</p>'}<p class="sheet-key"><i></i> Cyan dot and ray mark the sampled maximum direction.</p><p>Pattern radius represents relative gain on a logarithmic scale, not distance. Antenna geometry uses a separate schematic scale.</p><div class="sheet-angle">Maximum direction <b>Az ${n(m.peakAz,1)}° · El ${n(m.peakEl,1)}°</b></div></section><section class="sheet-cuts"><h3>Elevation through maximum</h3><small>Azimuth ${n(m.peakAz,1)}° / ${n((m.peakAz+180)%360,1)}°</small>${elevationSvg}<h3>Azimuth at maximum elevation</h3><small>Elevation ${n(m.peakEl,1)}°</small>${azimuthSvg}<p>${s.dbiReference?'dBi rings use this model’s gain basis.':'Both cuts are relative to the model’s peak.'}<br>Cyan dots identify its sampled maximum.</p></section><section class="sheet-data"><h3>Model configuration</h3><dl>${rows.map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></section></div><div class="sheet-notes"><p><b>Model boundary.</b> ${m.engine==='nec2'?`NEC2++ thin-wire solve, ${m.nec.geometry.segmentCount} segments. ${esc(m.nec.geometry.returnDescription)}. Device-input Z: ${esc(ohms(m.matching.presented[0]))}. Ideal ${s.matchRatio}:1 ratio, assumed loss ${s.deviceLoss} dB; choke does not change SWR. Flat half-space; no coax, insulation, real core model, terrain or multiband stack. Bulk-mesh Z change: ${m.nec.convergence===null?'n/a':n(100*m.nec.convergence,1)+'%'}; feed bridge is unchanged by mesh refinement.`:'Preview uses prescribed currents and approximate ground reflection. Coupling, impedance, SWR, matching and installed realized gain are not solved.'}</p><p><b>Maximum direction.</b> One maximum on a 5° sampling grid is reported; equal lobes may share the same maximum. Electrically large or high antennas can have narrow lobes missed by this grid. North is the model’s orientation reference.</p></div><div class="sheet-foot"><span>FieldLab · Antenna Explorer</span><span>Letter · Landscape · 1 page</span><span>supergoldfish101.github.io/FieldLab/</span></div></article>`;
}
